css:
.button {
  border-radius: 8px;
  border: 1px solid transparent;
  padding: 0.6em 1.2em;
  font-size: 1em;
  font-weight: 500;
  font-family: inherit;
  background-color: #1a1a1a;
  cursor: pointer;
  color: #ede5ff;
  transition: 0.2s;
}

.button:hover {
  box-shadow: 0px 0px 17px -4px #976cff;
  border-color: #976cff;
  color: #f7f5ff;
  background-color: #2e2546;
}

.button:active {
  box-shadow: 0px 0px 17px -7px #976cff;
  border-color: #976cff;
  transform: scale(0.95);
}
